51	    public void addDimensionNameConstraints(DimensionRenamer renamer) {
52	        if (!allInputTypesPresent(2)) {
53	            return;
54	        }
55	
56	        // Well now we have potentially entered the wonderful world of "broadcasting"
57	        // https://docs.scipy.org/doc/numpy/user/basics.broadcasting.html
58	        // I'm not able to extract from that any unambiguous specification of which dimensions
59	        // should be "stretched" when the tensor do not have the same number of dimensions.
60	        // From trying this with TensorFlow it appears that the second tensor is matched to the
61	        // "end" (highest numbered) dimensions of the first, but I'm not sure whether this is generally true.
62	        // Anyway, we move the dimensions of b to the last dimensions of a (instead of by default, the first).
63	
64	        OrderedTensorType a = inputs.get(0).type().get();
